ALTER TABLE users MODIFY COLUMN role ENUM('CUSTOMER','ADMIN','DRIVER','KITCHEN','OWNER') NOT NULL;
ALTER TABLE products ADD COLUMN prep_station ENUM('KITCHEN','CASHIER') NOT NULL DEFAULT 'KITCHEN' AFTER active;
ALTER TABLE products ADD COLUMN stock_quantity INT UNSIGNED NOT NULL DEFAULT 100 AFTER prep_station;
ALTER TABLE order_items ADD COLUMN prep_station ENUM('KITCHEN','CASHIER') NOT NULL DEFAULT 'KITCHEN' AFTER quantity;
UPDATE products SET prep_station='CASHIER' WHERE category_id IN (SELECT id FROM categories WHERE LOWER(name) LIKE '%minum%' OR LOWER(name) LIKE '%drink%' OR LOWER(name) LIKE '%kopi%');
UPDATE order_items i JOIN products p ON p.id=i.product_id SET i.prep_station=p.prep_station;
CREATE TABLE order_stations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,station ENUM('KITCHEN','CASHIER') NOT NULL,status ENUM('QUEUED','PREPARING','READY') NOT NULL DEFAULT 'QUEUED',started_by BIGINT UNSIGNED NULL,ready_by BIGINT UNSIGNED NULL,started_at TIMESTAMP NULL,ready_at TIMESTAMP NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(started_by) REFERENCES users(id),FOREIGN KEY(ready_by) REFERENCES users(id),UNIQUE KEY uq_order_station(order_id,station),INDEX idx_order_stations_station_status(station,status,order_id));
CREATE TABLE stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NULL,order_id BIGINT UNSIGNED NULL,kind ENUM('STOCK_IN','ADJUSTMENT','SALE','RESTORE') NOT NULL,quantity_delta INT NOT NULL,balance_after INT UNSIGNED NOT NULL,reason VARCHAR(240) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(actor_id) REFERENCES users(id),FOREIGN KEY(order_id) REFERENCES orders(id),UNIQUE KEY uq_stock_order_kind_product(order_id,kind,product_id),INDEX idx_stock_product_date(product_id,created_at,id));
